function quoteSliderMeta(service){
 const value=quoteQuantities[service];
 if(service==="Photography")return {label:"Edited photographs",min:15,max:100,step:5,unit:"photos",note:"15 edited photographs included. Additional photographs are $2 each.",price:30};
 if(service==="Videography")return {label:"Coverage hours",min:1,max:10,step:1,unit:"hours",note:"One hour starts at $50. Extended coverage is quoted to suit the brief.",price:null};
 if(service==="Storybook")return {label:"Storybook pages",min:3,max:12,step:1,unit:"pages",note:"3 pages start at $30. Each additional page is $20.",price:30};
 if(service==="Drone")return {label:"Estimated flight time",min:5,max:60,step:5,unit:"minutes",note:"Drone production starts at $40; final pricing depends on location and requirements.",price:null};
 if(service==="Reels")return {label:"Video duration",min:30,max:120,step:15,unit:"seconds",note:"A 30-second reel starts at $40. Longer edits are quoted separately.",price:null};
 return {label:"Coverage hours",min:2,max:12,step:1,unit:"hours",note:"Tell us the coverage you need. Event packages are priced after reviewing the event brief.",price:null};
}
function quoteServicePrice(service,value){
 if(service==="Photography")return 30+Math.max(0,value-15)*2;
 if(service==="Storybook")return 30+Math.max(0,value-3)*20;
 if(service==="Drone"&&value===15)return 40;
 if(service==="Reels"&&value===30)return 40;
 if(service==="Videography"&&value===1)return 50;
 return null;
}
