// One delegated handler for all persistent page-shell controls.
document.addEventListener("click",function(event){
 const target=event.target instanceof Element?event.target:null;
 if(!target)return;
 const menu=target.closest(".menu-toggle");
 if(menu){const topbar=menu.closest(".topbar");if(topbar)topbar.classList.toggle("menu-open");return;}
 const panelButton=target.closest("[data-panel]");
 if(panelButton){event.preventDefault();openPanel(panelButton.dataset.panel);return;}
 const tile=target.closest(".spatial-tile");
 if(tile){
  const service=tile.dataset.service||"Photography";
  const mapped=service==="Digital Experiences"?"Storybook":service==="Events & Brands"?"Event Package":service==="Selected Work"||service==="Portraits & People"?"Photography":service;
  if(configs[mapped])openPanel(mapped);
  return;
 }
 if(target.closest(".panel-close")||target.id==="panel-backdrop"){closePanel();return;}
 if(target.closest("#basket-open")||target.closest("#total-open")){panelTitle.textContent="Your quote";renderBasket();return;}
 if(target.closest("#quote-submit")){
  if(!basket.length){notify("Add a service to your quote first");return;}
  renderQuoteForm();return;
 }
 if(target.closest("#floating-quote-open")){openPanel("Get a Quote");renderBasket();panelTitle.textContent="Your quote";return;}
});
